    public static Net7GuildMessagePresentation? Resolve(uint messageType, string otherName, string guildName)
    {
        if (messageType >= Entries.Length)
            return null; // safety rule: 0083D900 returns null; 0073EB91 reads it before any presentation.
        Entry entry = Entries[checked((int)messageType)];
        string formatted = entry.Template
            .Replace("$OtherName$", otherName ?? string.Empty, StringComparison.Ordinal)
            .Replace("$GuildName$", guildName ?? string.Empty, StringComparison.Ordinal);
        string[] lines = formatted.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        Net7GuildMessagePresentationKind kind = messageType switch
        {
            2 => Net7GuildMessagePresentationKind.SecondaryList,
            3 => Net7GuildMessagePresentationKind.GuildRoster,
            4 => Net7GuildMessagePresentationKind.GuildWindowSuppressed,
            _ => Net7GuildMessagePresentationKind.OrdinaryGuildMessage,
        };
        return new Net7GuildMessagePresentation(messageType, entry.Sound, entry.Template, formatted, kind, lines);
    }
